WITH "r0" AS ( SELECT "s".* FROM "public"."author" AS "s" WHERE true AND ( ( true ) ) ORDER BY "s"."id" ASC NULLS LAST LIMIT 2000 ) SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."name" AS "name" , coalesce( "c2"."j" , '[]'::json ) AS "articles" ) AS "%")) ORDER BY "t0"."id" ASC NULLS LAST ), '[]') FROM "r0" AS "t0" LEFT JOIN (WITH "r1" AS ( SELECT "s".* FROM "public"."article" AS "s" WHERE ( "s"."author_id" ) IN (SELECT "id" FROM "r0" ) AND ( ( true ) ) ) SELECT "t1"."author_id" AS "k0" , coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" , "t1"."title" AS "title" , coalesce( "c2"."j" , '[]'::json ) AS "comments" ) AS "%")) ), '[]') AS "j" FROM "r1" AS "t1" LEFT JOIN (WITH "r2" AS ( SELECT "s".* FROM "public"."comment" AS "s" WHERE ( "s"."article_id" ) IN (SELECT "id" FROM "r1" ) AND ( ( true ) ) ) SELECT "t2"."article_id" AS "k0" , coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t2"."body" AS "body" ) AS "%")) ), '[]') AS "j" FROM "r2" AS "t2" GROUP BY "t2"."article_id" ) AS "c2" ON true AND "c2"."k0" = "t1"."id" GROUP BY "t1"."author_id" ) AS "c2" ON true AND "c2"."k0" = "t0"."id"
